// Array of 12 values [Jan, Feb, Mar, Apr, May, Jun, Jul, Aug, Sep, Oct, Nov, Dec]
// Watering/Misting: interval in days (0 = skip this month — dormancy)
// Fertilizing: interval in days (0 = don't fertilize this month)
export type MonthlyValues = readonly [
  number,
  number,
  number,
  number,
  number,
  number,
  number,
  number,
  number,
  number,
  number,
  number,
]

export interface PlantTemplate {
  name: string
  species: string
  careNotes: string
  difficulty: 'łatwa' | 'średnia' | 'trudna'
  light: 'cień' | 'półcień' | 'jasne' | 'pełne słońce'

  // Seasonal data (calibrated for Poland)
  wateringByMonth: MonthlyValues
  fertilizingByMonth: MonthlyValues // 0 = don't fertilize
  mistingByMonth: MonthlyValues // 0 = don't mist
  repottingMonths: readonly number[] // months 1–12
  pruningMonths: readonly number[] // months 1–12
  cleaningIntervalDays?: number // undefined = don't clean leaves (cacti, hairy leaves, etc.)
}

